import React, { useState, useEffect } from 'react';
import { fetchDriverInfo } from '../utils/api.js'; // We'll assume this fetches the mock JSON

function TransportStatus({ isEasyMode, goToDashboard }) {
    const [driverInfo, setDriverInfo] = useState(null);

    // Mock API call on component mount
    useEffect(() => {
        // Assume fetchDriverInfo returns the mock data immediately
        setDriverInfo(fetchDriverInfo()); 
    }, []);

    if (!driverInfo) {
        return <h2 style={{fontSize: isEasyMode ? '48px' : '24px'}}>Loading Transport Info...</h2>;
    }

    return (
        <div style={{ padding: '20px', textAlign: 'center' }}>
            <h2 style={{fontSize: isEasyMode ? '48px' : '24px'}}>Your Assigned Ride</h2>

            {/* Driver Photo/Name - Top-Left */}
            <div style={{
                display: 'flex', 
                flexDirection: 'column', 
                alignItems: 'center', 
                margin: '20px 0', 
                padding: '20px', 
                border: '3px solid #333'
            }}>
                {/*  */}
                <span role="img" aria-label="Driver" style={{fontSize: isEasyMode ? '100px' : '50px'}}>🧑‍✈️</span>
                <p style={{fontSize: isEasyMode ? '36px' : '20px', fontWeight: 'bold'}}
                   onClick={() => isEasyMode && console.log(`Audio: 'Your driver is ${driverInfo.name}.'`)}>
                    {driverInfo.name}
                </p>
            </div>

            {/* Car Details - Right Side */}
            <div style={{ display: 'flex', justifyContent: 'space-around', margin: '20px 0' }}>
                <div style={{ textAlign: 'center' }}>
                    {/* 

[Image of car placeholder]
 */}
                    <span role="img" aria-label="Car Type" style={{fontSize: isEasyMode ? '80px' : '40px'}}>🚗</span>
                    <p style={{fontSize: isEasyMode ? '28px' : '16px'}}>
                        {driverInfo.carType}
                    </p>
                </div>
                <div style={{ textAlign: 'center' }}>
                    <span role="img" aria-label="License Plate" style={{fontSize: isEasyMode ? '80px' : '40px'}}>🪪</span>
                    <p style={{fontSize: isEasyMode ? '28px' : '16px'}}>
                        Plate: **{driverInfo.licensePlate}**
                    </p>
                    <p style={{fontSize: isEasyMode ? '28px' : '16px'}}>
                        Color: **{driverInfo.carColor}**
                    </p>
                </div>
            </div>

            {/* Edit/Return Button */}
            <button 
                onClick={goToDashboard} 
                style={{ 
                    marginTop: '30px', 
                    padding: '20px 60px', 
                    fontSize: isEasyMode ? '36px' : '20px',
                    backgroundColor: 'orange',
                    color: 'white',
                    border: 'none',
                    borderRadius: '10px'
                }}
            >
                <span role="img" aria-label="Home" style={{marginRight: '10px'}}>🏠</span>
                Go Home
            </button>
        </div>
    );
}

// Mock utility function for the frontend
fetchDriverInfo = () => ({
    name: 'Sarah K.',
    carType: 'Blue Minivan',
    carColor: 'Blue',
    licensePlate: 'ABC 1234',
    // ... other mocked data ...
});

export default TransportStatus;
